-- Weekly Case 2026-11-16: Norway Hits Pause on Data Centres
INSERT INTO public.weekly_cases (id, week_start, market_id, kind, presented_by, title, topic, status, opens_at, closes_at, content)
VALUES ('bf24b9cb-23f9-5616-b31d-30174e118ffd', '2026-11-16', 'cleanenergy', 'original', 'MarketLingo', 'Norway Hits Pause on Data Centres', 'Allocating scarce grid capacity between data centres', 'scheduled', '2026-11-16T08:00:00.000Z', '2026-11-23T08:00:00.000Z', $wc${"hook":"Norway's grid operator has 800 MW of data centres connected, 4,200 MW reserved and 9,100 MW queued. Then it hit pause. Who gets the next megawatt?","tension":"Norway wants data-centre investment but cannot connect everything requested without risking grid stability, and fairness to those already in the queue limits how it can choose.","disclosure":"Educational case built from public reporting as of November 10, 2026. It is not legal, investment or policy advice, and the rules described were still being drafted.","as_of":"2026-11-10","brief":["On Monday, November 9, 2026, Norway's grid operator Statnett said it was temporarily stopping new grid-capacity reservations for data centres. As of November 10, 2026, the pause runs until new technical requirements are approved by the regulator, and no later than August 1, 2027.","The reason is stability as much as supply. Large data centres can change their power use very quickly, which Statnett says creates challenges for stable operation of the grid. The requirements it is preparing cover when a data centre must stay connected during grid disturbances, how fast consumption may ramp up or down, and how to limit oscillations in the grid. The government announced a licensing scheme for existing and future data centres the same day.","The pause is not a general ban. Existing connections are unaffected, facilities that already have approved functional requirements can still connect, and regional-grid applications that are close to completion keep moving. Statnett also says it will not reassign capacity if that would disadvantage data centres ahead in the queue, and that it applies the measure in a neutral and non-discriminatory way.","The numbers explain the pressure. Data centres have 800 MW connected, 4,200 MW reserved and 9,100 MW in the connection queue, plus a further 18,000 MW of requests. Norway's peak national demand is a little over 25,000 MW. Reporting by Nordisk Post says ministers want new rules to favour facilities that provide essential services such as defence, healthcare and telecom, and are examining whether industry could help finance new generation, such as offshore wind, or whether the state should take stakes in projects judged especially valuable.","Industry groups warn that changing the rules could weaken investor confidence, and Google has said further expansion at one of its Norwegian sites could depend on the forthcoming rules."],"exhibits":[{"id":"capacity","title":"Data-centre capacity requests in Norway","note":"The right-hand column adds each row to the rows above it. Peak demand is a little over 25,000 MW, so the shares are slightly overstated. Figures are megawatts of power capacity, not energy consumed.","columns":["Category","Capacity","Running total, and share of peak demand"],"rows":[["Connected","800 MW","—"],["Reserved","4,200 MW","5,000 MW · 20%"],["In the connection queue","9,100 MW","14,100 MW · 56%"],["Further requests","18,000 MW","32,100 MW · 128%"],["Norway's peak national demand","a little over 25,000 MW","—"]],"source_ids":["unite","nordisk","techstartups"]},{"id":"scope","title":"What the pause covers","note":"Capacity will not be reassigned if that would disadvantage data centres ahead in the queue.","columns":["Paused","Still moving"],"rows":[["New capacity reservations for data centres","Facilities with approved functional requirements"],["New applications for technical approval","Existing grid connections"],["Earlier applications to connect directly to the 420 kV grid","Regional-grid applications close to completion"],["—","Some smaller facilities due to connect during the pause"]],"source_ids":["unite","nordisk","energynews"]}],"question":{"text":"You advise the working group that must draft the rule for who gets grid capacity once the pause ends. Statnett must stay neutral, queue positions matter, and the stability requirements are still being written. Recommend the allocation rule you would put in front of the minister, and defend it."},"response":{"parts":[{"id":"constraint","label":"Name the constraint","prompt":"What is actually scarce: megawatts, grid stability, or something else? Use two figures from the exhibits.","max_words":90,"minutes":2},{"id":"rule","label":"Your allocation rule","prompt":"Who gets capacity first, on what condition, and what happens to capacity that is reserved but unused? Be specific enough that Statnett could apply it.","max_words":150,"minutes":3},{"id":"losers","label":"Who loses","prompt":"Name who is worse off under your rule, the investor-confidence risk the industry has raised, and one step that reduces it.","max_words":100,"minutes":2},{"id":"signals","label":"How you would know","prompt":"Give two signals you would track after launch and the result that would make you change the rule.","max_words":70,"minutes":1.5}]},"sources":[{"id":"unite","title":"Statnett Pauses Data Center Grid Reservations Pending New Technical Rules","publisher":"Unite.AI","url":"https://www.unite.ai/statnett-pauses-data-center-grid-reservations-pending-new-technical-rules/","published":null,"accessed":"2026-11-10","tier":"secondary"},{"id":"nordisk","title":"Norway pauses new grid reservations for data centres","publisher":"Nordisk Post","url":"https://www.nordiskpost.com/2026/11/10/norway-data-centres-grid-reservations-pause/","published":"2026-11-10","accessed":"2026-11-10","tier":"secondary"},{"id":"techstartups","title":"Top Tech News Roundup for Today, November 9, 2026","publisher":"Tech Startups","url":"https://techstartups.com/2026/11/09/top-tech-news-roundup-for-today-november-9-2026-nvidias-200b-wipeout-googles-tpu-8tx-anthropic-ipo-tesla-refunds-more/","published":"2026-11-09","accessed":"2026-11-10","tier":"secondary"},{"id":"energynews","title":"Statnett suspends new grid capacity reservations for data centers","publisher":"Energy News","url":"https://energynews.pro/en/statnett-suspends-new-grid-capacity-reservations-for-data-centers","published":"2026-11-09","accessed":"2026-11-10","tier":"secondary"}]}$wc$::jsonb)
