INSERT INTO public.weekly_case_scoring (case_id, rubric, model_answer, common_traps, facts, time_sensitive, stale_after)
VALUES ('bf24b9cb-23f9-5616-b31d-30174e118ffd', $wc$[{"id":"diagnosis","name":"Diagnosis of the constraint","weight":25,"part_ids":["constraint"],"measures":"Whether the answer separates the volume problem (generation and transmission) from the stability problem (fast, unpredictable load swings).","excellent":"Names both scarcities, says which one the pause targets, and uses two figures correctly to show requests cannot all be served.","weak":"Says only that there is not enough power, or restates the figures without saying what they imply."},{"id":"rule","name":"A rule Statnett could apply","weight":25,"part_ids":["rule"],"measures":"Whether the rule has an ordering principle, conditions, and a way to deal with reserved capacity that goes unused.","excellent":"States who goes first and why, attaches checkable conditions or milestones, respects queue positions or explains the exception, and says what happens to released capacity.","weak":"Offers a vague priority such as favouring important projects, with no test, decision-maker or treatment of the existing queue."},{"id":"numbers","name":"Use of the numbers","weight":15,"part_ids":["all"],"measures":"Whether figures are used correctly and where they matter, across all parts.","excellent":"Uses at least two figures correctly, separates connected from reserved from requested, and does the comparison with peak demand without error.","weak":"Treats all requests as real demand, mixes megawatts with energy, or misstates a figure."},{"id":"tradeoffs","name":"Trade-offs and investor confidence","weight":20,"part_ids":["losers"],"measures":"Whether the answer is honest about who loses and deals with the investor-confidence risk raised by industry groups.","excellent":"Names the specific losers, explains why confidence is at risk, and proposes a concrete mitigation such as grandfathering or publishing criteria early.","weak":"Claims the rule is fair to everyone, or names a risk with no response to it."},{"id":"measure","name":"Measurability and a trigger to change course","weight":15,"part_ids":["signals"],"measures":"Whether the answer chooses signals that can be observed and says what result would change the rule.","excellent":"Two observable signals tied to the rule's goals and a clear trigger for revising it.","weak":"Generic signals such as success or satisfaction, with no trigger."}]$wc$::jsonb, $wc${"summary":"Keep queue order, but make reservations use-it-or-lose-it, and give released capacity to essential services and to projects that bring their own generation or accept flexibility.","parts":[{"part_id":"constraint","text":"The total of requests cannot all be served: 32,100 MW of connected, reserved, queued and further requests is about 128% of Norway's peak national demand of a little over 25,000 MW. Two scarcities sit under that number. One is volume, meaning generation and transmission to serve the load. The other is stability, meaning how fast and how unpredictably a data centre's load can swing. The pause targets the second. The talk of financing new generation targets the first."},{"part_id":"rule","text":"Honour reservations, but make them earn it. Only 800 MW is connected against 4,200 MW reserved, so unused reservations are the cheapest capacity to free. Keep queue order, because Statnett has said it will not disadvantage those ahead, but attach dated milestones: technical approval under the new stability requirements, a signed power contract, and construction start. A reservation that misses a milestone returns its capacity to a shared pool. Allocate the pool in rounds: first facilities providing essential services such as defence, healthcare and telecom, then projects that bring new generation or accept ramp limits and curtailment."},{"part_id":"losers","text":"Speculative developers who reserved without a ready project lose, and so do later entrants with no essential-service claim. The confidence risk is real because the rules change after reservations were made. Reduce it by grandfathering every reservation that meets its milestones, publishing the criteria and the timetable well before the pause ends, no later than August 1, 2027, and giving near-ready projects a clear route in."},{"part_id":"signals","text":"Track the share of reserved capacity that meets its milestones versus is released, and the time from approval to energisation. Change the rule if the shared pool stays empty because reservations are never released, or if essential-service projects crowd out everything else for a full allocation round."}],"alternatives":[{"option":"Pure queue order with technical requirements only","better_when":"Speed and legal certainty matter most and generation is not the binding limit."},{"option":"An auction or pay-to-connect scheme that funds new generation","better_when":"New generation is the binding limit and the state wants the industry to pay for it."},{"option":"State-led selection of a few strategic projects, possibly with state stakes","better_when":"The aim is a handful of nationally valuable projects rather than a broad market."}],"key_fact_ids":["conn","res","all","share_all","peak"]}$wc$::jsonb, $wc$[{"trap":"Writing as a data-centre operator asking for capacity","why":"The role is the allocator. The answer must be a rule that treats applicants even-handedly, not a pitch for one of them."},{"trap":"Treating the 32,100 MW of requests as real demand","why":"Reservations and requests are options on capacity. Only 800 MW is connected. A good answer separates intent from load and plans for attrition."},{"trap":"Ignoring queue positions and neutrality","why":"Statnett has said it will not reassign capacity to the disadvantage of those ahead in the queue and that it applies the pause neutrally. A rule that jumps the queue without a reason invites a challenge."},{"trap":"Answering 'build more generation' and stopping","why":"That may be right in the long run, but the decision is who gets scarce capacity when the pause ends, no later than August 1, 2027."},{"trap":"A priority list with no mechanism","why":"'Prioritise important projects' cannot be applied. Say who decides, on what test, and what happens to unused reservations."}]$wc$::jsonb, $wc$[{"id":"conn","label":"Data-centre capacity connected to the Norwegian grid","kind":"reported","display":"800 MW","value":800,"as_of":"2026-11-09","sources":["unite","nordisk","techstartups"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Connected to the grid: 800 MW"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Connected: 800 MW"}]},{"id":"res","label":"Data-centre capacity reserved","kind":"reported","display":"4,200 MW","value":4200,"as_of":"2026-11-09","sources":["unite","nordisk","techstartups"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Reserved capacity: 4,200 MW"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Reserved: 4,200 MW"}]},{"id":"queue","label":"Data-centre capacity in the connection queue","kind":"reported","display":"9,100 MW","value":9100,"as_of":"2026-11-09","sources":["unite","nordisk","techstartups"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"In the capacity queue: 9,100 MW"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Connection queue: 9,100 MW"}]},{"id":"enq","label":"Further capacity requested, separate from the above","kind":"reported","display":"18,000 MW","value":18000,"as_of":"2026-11-09","sources":["unite","nordisk","techstartups"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Additional requests submitted, separate from the above: 18,000 MW"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Preliminary enquiries: a further 18,000 MW"}]},{"id":"peak","label":"Norway's peak national power demand (approximate)","kind":"reported","display":"25,000 MW","value":25000,"as_of":"2026-11-09","sources":["unite","techstartups"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Norway's maximum power consumption: a little over 25,000 MW (no exact figure given)"},{"pass":2,"source_id":"techstartups","method":"quote","checked_on":"2026-11-10","evidence":"Norway's peak national demand slightly above 25,000 MW"}]},{"id":"kv","label":"Voltage of the transmission grid some paused applications target","kind":"reported","display":"420 kV","value":420,"as_of":"2026-11-09","sources":["unite","nordisk"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"facilities connecting directly to the 420 kV network"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"direct connections to the 420-kV network"}]},{"id":"pause_start","label":"Date Statnett announced the pause","kind":"reported","display":"November 9, 2026","as_of":"2026-11-09","sources":["unite","nordisk"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Announcement date: November 9, 2026"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Announcement date: Monday, 9 November 2026"}]},{"id":"pause_end","label":"Latest date the pause is expected to end","kind":"reported","display":"August 1, 2027","as_of":"2026-11-09","sources":["unite","nordisk"],"verified":[{"pass":1,"source_id":"unite","method":"quote","checked_on":"2026-11-10","evidence":"Expected pause end: no later than August 1, 2027"},{"pass":2,"source_id":"nordisk","method":"quote","checked_on":"2026-11-10","evidence":"Pause end: no later than 1 August 2027"}]},{"id":"reserved_connected","label":"Connected plus reserved","kind":"derived","display":"5,000 MW","value":5000,"formula":"conn + res","inputs":["conn","res"],"decimals":0,"as_of":"2026-11-09"},{"id":"committed","label":"Connected, reserved and queued","kind":"derived","display":"14,100 MW","value":14100,"formula":"conn + res + queue","inputs":["conn","res","queue"],"decimals":0,"as_of":"2026-11-09"},{"id":"all","label":"Connected, reserved, queued and further requests","kind":"derived","display":"32,100 MW","value":32100,"formula":"committed + enq","inputs":["committed","enq"],"decimals":0,"as_of":"2026-11-09"},{"id":"share_rc","label":"Connected plus reserved as a share of peak demand","kind":"derived","display":"20%","value":20,"formula":"reserved_connected / peak","scale":100,"inputs":["reserved_connected","peak"],"decimals":0,"as_of":"2026-11-09"},{"id":"share_c","label":"Connected, reserved and queued as a share of peak demand","kind":"derived","display":"56%","value":56,"formula":"committed / peak","scale":100,"inputs":["committed","peak"],"decimals":0,"as_of":"2026-11-09"},{"id":"share_all","label":"All requests as a share of peak demand","kind":"derived","display":"128%","value":128,"formula":"all / peak","scale":100,"inputs":["all","peak"],"decimals":0,"as_of":"2026-11-09"}]$wc$::jsonb, $wc$[{"claim":"The pause lasts until regulator-approved technical requirements are in place, and no later than August 1, 2027.","as_of":"2026-11-10","check_again_by":"2026-11-23"},{"claim":"The licensing scheme and any priority for essential services are announced intentions, not adopted rules.","as_of":"2026-11-10","check_again_by":"2026-11-23"}]$wc$::jsonb, '2026-11-30')
