-- Weekly Case 2026-11-23: Duolingo: Users Up 29%, Bookings Up 12%
INSERT INTO public.weekly_cases (id, week_start, market_id, kind, presented_by, title, topic, status, opens_at, closes_at, content)
VALUES ('5a9f4671-ea83-5e52-9578-df5dbebf99fb', '2026-11-23', 'ai', 'original', 'MarketLingo', 'Duolingo: Users Up 29%, Bookings Up 12%', 'Turning a fast-growing free user base into paying subscribers without hurting the free product', 'scheduled', '2026-11-23T08:00:00.000Z', '2026-11-30T08:00:00.000Z', $wc${"hook":"Duolingo's daily users grew 29% in a year, but bookings grew 12%. Management says 2027 leans into monetization. Which lever goes first?","tension":"A much larger free base is a long-term asset only if it converts, yet pushing conversion too hard could damage the free experience that drives the growth.","disclosure":"Educational case built from public company reports as of November 10, 2026. It is not investment advice, and the ratios in Exhibit 2 are our arithmetic, not figures the company reports.","as_of":"2026-11-10","brief":["Duolingo reported third-quarter 2026 results on November 3, 2026. Daily active users reached 64.9M, up 29% from 50.5M a year earlier and faster than the 23% growth of the previous quarter. Paid subscribers reached 13.1M, up 14% from 11.5M. Total bookings, the money customers committed to spend in the quarter, were $316.1M, up 12% from $281.9M.","Users are growing faster than revenue. Subscription bookings rose 16% to $278.4M. Outside subscriptions the picture is weaker: advertising revenue was roughly flat at $20.8M, down 1%, and in-app purchase revenue fell 38% to $6.9M. Duolingo also accrued $11.4M in the quarter for a company-wide bonus tied to Q4 daily-user growth of 25% or greater.","Management says 2027 will lean more into monetization after a year focused on teaching quality and user growth, but with a firm internal rule not to make the free experience worse. It says a much larger active base is a long-term asset because some users take years to convert, and it gave no free-to-paid conversion rate. It also says paid subscriber growth is slowing and should bottom within a couple of quarters.","As of the November 3, 2026 call, the levers management has named are: longer free trials, which it says raise conversion and which it plans to expand; higher-quality advertising in place of low-quality ad networks, which it says will take time; in-app purchases such as avatar suits; Chess, which reached 10M daily users and which it calls under-monetized; a cheaper ad-supported tier, where tests have not been big wins; and the Family plan. Duolingo is also retiring its highest tier, Max, now a single-digit share of paid subscribers and bookings, because AI video calls that once cost about $0.30 each now cost under $0.01 and move into the Super tier.","Gross margin was 72.9% in the quarter. Duolingo guides to 72.0% for Q4 as video calls roll out to all paid subscribers."],"exhibits":[{"id":"q3","title":"Exhibit 1. Third quarter, 2025 and 2026","note":"Daily and monthly users and subscribers are for the quarter or its end. Advertising and in-app purchases are revenue, not bookings.","columns":["Metric","Q3 2025","Q3 2026","Change"],"rows":[["Daily active users","50.5M","64.9M","29%"],["Monthly active users","135.3M","153.1M","13%"],["Paid subscribers","11.5M","13.1M","14%"],["Total bookings","$281.9M","$316.1M","12%"],["Subscription bookings","$240.3M","$278.4M","16%"],["Advertising revenue","$21.0M","$20.8M","-1%"],["In-app purchase revenue","$11.1M","$6.9M","-38%"]],"source_ids":["letter","tenq"]},{"id":"ratios","title":"Exhibit 2. Worked ratios (our arithmetic)","note":"Each ratio divides one reported figure by another for the same quarter. Read them as direction, not as a price or a conversion rate.","columns":["Ratio","Q3 2025","Q3 2026","Change"],"rows":[["Paid subscribers as a share of monthly users","8.5%","8.6%","—"],["Paid subscribers as a share of daily users","22.8%","20.2%","—"],["Total bookings per daily user","$5.58","$4.87","-12.7%"],["Bookings outside subscriptions","$41.6M","$37.7M","-9.4%"]],"source_ids":["letter"]}],"question":{"text":"You lead monetization planning for Duolingo's 2027 plan. Management says it will lean further into monetization but will not make the free experience worse. Choose the one lever you would scale first, and defend the choice with the numbers."},"response":{"parts":[{"id":"read","label":"Read the numbers","prompt":"What do the ratios say about the new daily users? Is the gap between user growth and bookings a problem, or a delay?","max_words":90,"minutes":2},{"id":"lever","label":"Your lever","prompt":"Pick one lever from the brief, or propose another. Say who it targets, what you expect to change, and why it goes first.","max_words":140,"minutes":2.5},{"id":"test","label":"Test and guardrail","prompt":"What would you measure, what protects the free experience, and what result would make you stop?","max_words":100,"minutes":2},{"id":"risk","label":"Biggest risk","prompt":"What is the most likely way this goes wrong, and what would you do about it?","max_words":60,"minutes":1.5}]},"sources":[{"id":"letter","title":"Duolingo Q3 2026 shareholder letter (Form 8-K exhibit)","publisher":"U.S. Securities and Exchange Commission, filed by Duolingo, Inc.","url":"https://www.sec.gov/Archives/edgar/data/1562088/000162828026069474/q3fy26duolingo9-30x26share.htm","published":"2026-11-03","accessed":"2026-11-10","tier":"primary"},{"id":"tenq","title":"Duolingo Form 10-Q for the quarter ended September 30, 2026","publisher":"U.S. Securities and Exchange Commission, filed by Duolingo, Inc.","url":"https://www.sec.gov/Archives/edgar/data/0001562088/000162828026069692/duol-20260930.htm","published":null,"accessed":"2026-11-10","tier":"primary"},{"id":"yahoo","title":"Duolingo Inc (DUOL) Q3 2026 Earnings Call Highlights","publisher":"GuruFocus, syndicated on Yahoo Finance","url":"https://finance.yahoo.com/markets/stocks/articles/duolingo-inc-duol-q3-2026-050948751.html","published":null,"accessed":"2026-11-10","tier":"secondary"},{"id":"investing","title":"Earnings call transcript: Duolingo Q3 2026 revenue beats as users accelerate","publisher":"Investing.com","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-duolingo-q3-2026-revenue-beats-as-users-accelerate-93CH-4996909","published":null,"accessed":"2026-11-10","tier":"secondary"},{"id":"aware","title":"Duolingo Q3 2026: DAUs Surge 29%, Guidance Raised, and Max Tier Sunsets","publisher":"AWARE","url":"https://awareinvest.com/terminal/intel/duolingo-q3-2026-daus-surge-29-guidance-raised-and-max-tier-sunsets-2026-11-03-1794c2336c295426f10bdaf6ea9ac27d","published":"2026-11-03","accessed":"2026-11-10","tier":"secondary"}]}$wc$::jsonb)
